import "server-only";
import { randomUUID } from "node:crypto";
import { z } from "zod";
import type { Prisma } from "@/generated/prisma/client";
import { db } from "@/lib/db";
import { deletionSubjectHash } from "@/lib/deletion-identity";
import { decryptToken } from "@/lib/crypto";
import { deleteOwnedResumes } from "@/lib/storage";
import { cancelDeletionBilling } from "@/lib/billing/deletion";

export const DELETION_DRAIN_MS = 15 * 60000;
export const DELETION_RETENTION_MS = 30 * 86400000;
export const DELETION_SWEEP_INTERVAL_MS = 86400000;
export const deletionCheckoutSchema = z.array(
  z.object({
    id: z.string(),
    sessionId: z.string().nullable(),
    expiresAt: z.string(),
    createdAt: z.string(),
    status: z.string(),
  }),
);
export function cancellationBackoff(failures: number) {
  return Math.min(3600000, 60000 * 2 ** Math.min(Math.max(0, failures - 1), 6));
}

/** Pre-migration deleted owners may have only retained billing snapshots.
 * Their Google subject/credential cannot be reconstructed; retain the missing
 * external erasure proof for manual review rather than fabricating completion. */
export async function recoverRetainedDeletion(
  userId: string,
  customerId: string,
) {
  const subscriptions = await db.billingSubscription.findMany({
    where: { userId: null, ownerIdSnapshot: userId },
    select: { dodoSubscriptionId: true, dodoCustomerId: true },
  });
  const attempts = await db.checkoutAttempt.findMany({
    where: { userId: null, ownerIdSnapshot: userId },
  });
  const now = new Date();
  await db.accountDeletionJob.upsert({
    where: { userId },
    create: {
      userId,
      requestedAt: now,
      credentialExpiresAt: now,
      nextAttemptAt: now,
      nextBillingAttemptAt: now,
      contentDeletedAt: now,
      googleRevocationIncomplete: true,
      credentialErasedAt: now,
      customerIds: [
        ...new Set([customerId, ...subscriptions.map((s) => s.dodoCustomerId)]),
      ],
      subscriptionIds: subscriptions.map((s) => s.dodoSubscriptionId),
      billingRequired: true,
      checkoutRecovery: attempts.map((a) => ({
        id: a.id,
        sessionId: a.dodoSessionId,
        expiresAt: a.expiresAt.toISOString(),
        createdAt: a.createdAt.toISOString(),
        status: a.status,
      })),
    },
    update: {},
  });
}

/** Called under the User lock, before deleting any ordinary data. Only recovery
 * identifiers and a deadline-limited encrypted credential leave the account. */
export async function ensureDeletionJob(
  tx: Prisma.TransactionClient,
  userId: string,
) {
  const user = await tx.user.findUniqueOrThrow({ where: { id: userId } });
  if (!user.deletionRequestedAt) throw new Error("Deletion was not requested.");
  await tx.$queryRaw`SELECT id FROM "AccountDeletionJob" WHERE "userId" = ${userId} FOR UPDATE`;
  const subscriptions = await tx.billingSubscription.findMany({
    where: { userId },
    select: { dodoSubscriptionId: true, dodoCustomerId: true },
  });
  const attempts = await tx.checkoutAttempt.findMany({ where: { userId } });
  const old = await tx.accountDeletionJob.findUnique({ where: { userId } });
  const checkoutRecovery = [
    ...deletionCheckoutSchema.parse(old?.checkoutRecovery ?? []),
  ];
  for (const attempt of attempts) {
    const value = {
      id: attempt.id,
      sessionId: attempt.dodoSessionId,
      expiresAt: attempt.expiresAt.toISOString(),
      createdAt: attempt.createdAt.toISOString(),
      status: attempt.status,
    };
    const index = checkoutRecovery.findIndex((a) => a.id === attempt.id);
    if (index < 0) checkoutRecovery.push(value);
    else checkoutRecovery[index] = value;
  }
  const requestedAt = old?.requestedAt ?? user.deletionRequestedAt;
  const deadline = new Date(+requestedAt + DELETION_RETENTION_MS);
  const retainCredential = Date.now() + DELETION_SWEEP_INTERVAL_MS < +deadline;
  const values = {
    customerIds: [
      ...new Set([
        ...(old?.customerIds ?? []),
        ...subscriptions.map((s) => s.dodoCustomerId),
        ...(user.dodoCustomerId ? [user.dodoCustomerId] : []),
      ]),
    ],
    subscriptionIds: [
      ...new Set([
        ...(old?.subscriptionIds ?? []),
        ...subscriptions.map((s) => s.dodoSubscriptionId),
        ...(user.dodoSubscriptionId ? [user.dodoSubscriptionId] : []),
      ]),
    ],
    checkoutRecovery,
  };
  return tx.accountDeletionJob.upsert({
    where: { userId },
    create: {
      userId,
      requestedAt,
      nextAttemptAt: requestedAt,
      nextBillingAttemptAt: requestedAt,
      credentialExpiresAt: deadline,
      googleSubjectHash: user.googleId
        ? deletionSubjectHash(user.googleId)
        : null,
      encryptedRevocationToken: retainCredential
        ? user.encryptedRefreshToken
        : null,
      googleRevokedAt: user.encryptedRefreshToken ? null : new Date(),
      googleRevocationIncomplete: Boolean(
        user.encryptedRefreshToken && !retainCredential,
      ),
      credentialErasedAt:
        user.encryptedRefreshToken && !retainCredential ? new Date() : null,
      ...values,
      billingRequired: Boolean(
        values.customerIds.length ||
        values.subscriptionIds.length ||
        attempts.length,
      ),
    },
    update: {
      ...values,
      ...(values.customerIds.length ||
      values.subscriptionIds.length ||
      attempts.length
        ? { billingRequired: true }
        : {}),
      ...(old &&
      (JSON.stringify(old.customerIds) !== JSON.stringify(values.customerIds) ||
        JSON.stringify(old.subscriptionIds) !==
          JSON.stringify(values.subscriptionIds) ||
        JSON.stringify(old.checkoutRecovery) !==
          JSON.stringify(values.checkoutRecovery))
        ? {
            billingRecoveryVersion: { increment: 1 },
            billingCancelledAt: null,
            nextBillingAttemptAt: requestedAt,
            completedAt: null,
          }
        : {}),
    },
  });
}

async function purgeContent(userId: string, token: string, now: Date) {
  return db.$transaction(async (tx) => {
    // Same lock ordering as claims, checkout and deletion requests.
    await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
    const job = await tx.accountDeletionJob.findFirst({
      where: { userId, leaseToken: token, leaseExpiresAt: { gt: now } },
    });
    if (!job) throw new Error("DELETION_LEASE_LOST");
    const user = await tx.user.findUnique({ where: { id: userId } });
    if (user) {
      if (
        !user.deletionRequestedAt ||
        +user.deletionRequestedAt + DELETION_DRAIN_MS > +now
      )
        return;
      const recovery = await ensureDeletionJob(tx, userId);
      // Reservation FKs restrict period deletion, attachment FKs restrict User cascade.
      await tx.usageReservation.deleteMany({ where: { userId } });
      await tx.usageImportEvidence.deleteMany({ where: { userId } });
      await tx.usagePeriod.deleteMany({ where: { userId } });
      await tx.campaign.deleteMany({ where: { userId } });
      await tx.billingWebhookEvent.deleteMany({
        where: {
          OR: [
            { customerId: { in: recovery.customerIds } },
            { subscriptionId: { in: recovery.subscriptionIds } },
            {
              normalizedData: {
                path: ["metadata", "mailloopUserId"],
                equals: userId,
              },
            },
          ],
        },
      });
      await tx.checkoutAttempt.deleteMany({ where: { userId } });
      await tx.billingSubscription.deleteMany({ where: { userId } });
      // Immutable operator events retain UUID snapshots; FK deletion nulls live references.
      await tx.user.deleteMany({
        where: { id: userId, deletionRequestedAt: { not: null } },
      });
    }
    await tx.accountDeletionJob.updateMany({
      where: { userId, leaseToken: token },
      data: { contentDeletedAt: now },
    });
  });
}

/** Recover legacy requests under the owner lock before daily job discovery. */
export async function prepareDeletionJob(userId: string) {
  const legacy = await db.user.findFirst({
    where: { id: userId, deletionRequestedAt: { not: null } },
    select: { id: true },
  });
  if (legacy)
    await db.$transaction(async (tx) => {
      await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
      if (
        await tx.user.findFirst({
          where: { id: userId, deletionRequestedAt: { not: null } },
        })
      )
        await ensureDeletionJob(tx, userId);
    });
}

/** CAS leases and persisted stage results keep daily retries safe.
 * Billing-only calls never start physical cleanup. */
export async function runDeletionJob(
  userId: string,
  now = new Date(),
  options: { billingOnly?: boolean } = {},
) {
  await prepareDeletionJob(userId);
  const token = randomUUID();
  const claimed = await db.accountDeletionJob.updateMany({
    where: {
      userId,
      nextAttemptAt: { lte: now },
      AND: [
        { completedAt: null },
        { OR: [{ leaseExpiresAt: null }, { leaseExpiresAt: { lte: now } }] },
      ],
    },
    data: {
      leaseToken: token,
      leaseExpiresAt: new Date(+now + 10 * 60000),
      nextAttemptAt: new Date(+now + 60000),
    },
  });
  if (!claimed.count) return false;
  const update = (data: Prisma.AccountDeletionJobUpdateManyMutationInput) =>
    db.accountDeletionJob.updateMany({
      where: { userId, leaseToken: token },
      data,
    });
  try {
    let job = await db.accountDeletionJob.findUniqueOrThrow({
      where: { userId },
    });
    // Deadline is checked before any external call, even if Google never responds.
    if (now >= job.credentialExpiresAt && job.encryptedRevocationToken)
      await update({
        encryptedRevocationToken: null,
        credentialErasedAt: now,
        googleRevocationIncomplete: !job.googleRevokedAt,
      });
    const drained = +now >= +job.requestedAt + DELETION_DRAIN_MS;
    if (drained && !options.billingOnly) {
      // Independent stages start before billing, which may be unavailable indefinitely.
      if (!job.contentDeletedAt) {
        try {
          await purgeContent(userId, token, now);
          await update({ purgeFailureCode: null });
        } catch {
          await update({ purgeFailureCode: "CONTENT_PURGE_FAILED" });
        }
      }
      if (!job.storageDeletedAt) {
        try {
          await deleteOwnedResumes(userId);
          await update({ storageDeletedAt: now });
        } catch {
          await update({ purgeFailureCode: "STORAGE_PURGE_FAILED" });
        }
      }
      job = await db.accountDeletionJob.findUniqueOrThrow({
        where: { userId },
      });
      if (
        !job.googleRevokedAt &&
        job.encryptedRevocationToken &&
        now < job.credentialExpiresAt
      ) {
        try {
          const response = await fetch("https://oauth2.googleapis.com/revoke", {
            method: "POST",
            headers: { "Content-Type": "application/x-www-form-urlencoded" },
            body: new URLSearchParams({
              token: decryptToken(job.encryptedRevocationToken, job.userId),
            }),
            signal: AbortSignal.timeout(15000),
          });
          if (response.ok || response.status === 400)
            await update({
              googleRevokedAt: now,
              encryptedRevocationToken: null,
              credentialErasedAt: now,
            });
        } catch {
          /* Independent retry until credential expiry. */
        }
      }
    }
    job = await db.accountDeletionJob.findUniqueOrThrow({ where: { userId } });
    if (!job.billingCancelledAt && job.nextBillingAttemptAt <= now) {
      await update({
        cancellationAttempts: { increment: 1 },
        nextBillingAttemptAt: new Date(
          +now + cancellationBackoff(job.cancellationFailures + 1),
        ),
      });
      try {
        const stopped =
          !job.billingRequired || (await cancelDeletionBilling(userId));
        if (!stopped) throw new Error("BILLING_CANCELLATION_PENDING");
        await db.accountDeletionJob.updateMany({
          where: {
            userId,
            leaseToken: token,
            billingRecoveryVersion: job.billingRecoveryVersion,
          },
          data: { billingCancelledAt: now, failureCode: null },
        });
      } catch {
        await update({
          cancellationFailures: { increment: 1 },
          failureCode: "BILLING_CANCELLATION_PENDING",
        });
      }
    }
    job = await db.accountDeletionJob.findUniqueOrThrow({ where: { userId } });
    if (job.contentDeletedAt && job.storageDeletedAt && job.purgeFailureCode)
      await update({ purgeFailureCode: null });
    const complete = Boolean(
      job.contentDeletedAt &&
      job.storageDeletedAt &&
      job.billingCancelledAt &&
      job.googleRevokedAt,
    );
    // Keep failed revocation tombstones visible until operator/provider confirms erasure.
    if (complete)
      await db.accountDeletionJob.updateMany({
        where: {
          userId,
          leaseToken: token,
          billingRecoveryVersion: job.billingRecoveryVersion,
          billingCancelledAt: { not: null },
        },
        data: {
          completedAt: job.completedAt ?? now,
          googleSubjectHash: null,
          checkoutRecovery: [],
        },
      });
    return complete;
  } finally {
    await update({ leaseToken: null, leaseExpiresAt: null });
  }
}

// Erase one daily interval early so the normal next sweep stays within day 30.
// This runs independently of leases and provider retry schedules.
export async function expireDeletionCredentials(now = new Date()) {
  const cutoff = new Date(+now + DELETION_SWEEP_INTERVAL_MS);
  await db.accountDeletionJob.updateMany({
    where: {
      credentialExpiresAt: { lte: cutoff },
      encryptedRevocationToken: { not: null },
    },
    data: {
      encryptedRevocationToken: null,
      credentialErasedAt: now,
      googleRevocationIncomplete: true,
    },
  });
  const legacy = await db.user.findMany({
    where: {
      deletionRequestedAt: { lte: new Date(+cutoff - DELETION_RETENTION_MS) },
      encryptedRefreshToken: { not: null },
    },
    select: { id: true },
  });
  for (const { id: userId } of legacy) {
    try {
      await db.$transaction(async (tx) => {
        await tx.$queryRaw`SELECT id FROM "User" WHERE id = ${userId} FOR UPDATE`;
        if (
          !(await tx.user.findFirst({
            where: { id: userId, deletionRequestedAt: { not: null } },
          }))
        )
          return;
        await ensureDeletionJob(tx, userId);
        await tx.accountDeletionJob.updateMany({
          where: { userId },
          data: {
            encryptedRevocationToken: null,
            credentialErasedAt: now,
            googleRevokedAt: null,
            googleRevocationIncomplete: true,
          },
        });
      });
    } finally {
      await db.user.updateMany({
        where: { id: userId, deletionRequestedAt: { not: null } },
        data: { encryptedRefreshToken: null },
      });
    }
  }
}
